    errors.append(f'top-level keys/order: {list(out.keys())}')
if set(out.keys()) != {'schema_version','inventory_sha256','rules'}:
    errors.append('top-level key set mismatch')
if out['schema_version'] != 2:
    errors.append('schema_version')
if out['inventory_sha256'] != inv['inventory_sha256']:
    errors.append('inventory_sha256')
canonical=[r['source_rule_id'] for r in inv['rules']]
actual=[r['source_rule_id'] for r in out['rules']]
if actual != canonical:
    errors.append('rule order/content differs')
counts=collections.Counter(actual)
if any(n != 1 for n in counts.values()) or len(counts) != len(canonical):
    errors.append('duplicate/missing ids')
allowed={'DEFINITION','OPERATIONAL_RULE','PROVED_DERIVED_LEMMA','DOMAIN_LEMMA'}
for i,r in enumerate(out['rules']):
    if set(r) != {'source_rule_id','classification','rationale'}:
        errors.append(f'entry {i} keys {set(r)}')
    if r['classification'] not in allowed:
        errors.append(f'entry {i} classification')
    if not isinstance(r['rationale'],str) or not r['rationale'].strip():
        errors.append(f'entry {i} rationale')
for src,dst in zip(inv['rules'],out['rules']):
    if 'simplification' in src.get('attributes',[]) and dst['classification'] not in {'DEFINITION','DOMAIN_LEMMA'}:
        errors.append(f'simplification classified {dst["classification"]}: {dst["source_rule_id"]}')
class_counts=collections.Counter(r['classification'] for r in out['rules'])
print('canonical_count=',len(canonical))
print('output_count=',len(actual))
print('inventory_sha256=',out['inventory_sha256'])
print('classification_counts=',dict(class_counts))
print('simplification_count=',sum('simplification' in r.get('attributes',[]) for r in inv['rules']))
print('duplicate_ids=',[k for k,v in counts.items() if v != 1])
print('errors=',errors)
print('discovery_nonempty=',pathlib.Path('/workspace/DISCOVERY.md').stat().st_size > 0)
sys.exit(bool(errors))
