#define _GNU_SOURCE
#include <fcntl.h>
#include <stddef.h>
#include <string.h>
#include <sys/syscall.h>
#include <unistd.h>

ssize_t readlink(const char *restrict path, char *restrict buf, size_t bufsiz) {
    const char *effective = path;
    size_t len = strlen(path);
    if (len > 10 && strncmp(path, "/proc/", 6) == 0
        && strcmp(path + len - 4, "/exe") == 0) {
        effective = "/proc/self/exe";
    }
    return syscall(SYS_readlinkat, AT_FDCWD, effective, buf, bufsiz);
}
